    {"name": "edit", "arguments": {"path": "shipping/quote.py", "range": "7vr-9sa", "new": "def quote(order):\n    \"\"\"The quote for `order`, as described in the README.\"\"\"\n    try:\n        items = order[\"items\"]\n        service = order[\"service\"]\n        if not items:\n            raise QuoteError(\"An order must contain items\")\n        for item in items:\n            qty = item[\"qty\"]\n            if isinstance(qty, bool) or not isinstance(qty, int) or qty <= 0:\n                raise QuoteError(\"qty must be a positive integer\")\n            weight = item[\"weight_g\"]\n            if isinstance(weight, bool) or not isinstance(weight, int) or weight <= 0:\n                raise QuoteError(\"weight_g must be a positive integer\")\n            dims = item[\"dims_cm\"]\n            if any(isinstance(side, bool) or not isinstance(side, int) or side <= 0 for side in dims):\n                raise QuoteError(\"dimensions must be positive integers\")\n        if service not in (\"standard\", \"express\"):\n            raise QuoteError(\"Unknown service\")\n        zone, remote = zones.lookup(order[\"destination\"])\n        if service == \"express\" and zone in rates.EXPRESS_UNAVAILABLE_IN:\n            raise QuoteError(\"Express is unavailable in this zone\")\n        weight = weights.billable_g(items)\n        tariff = rates.ZONES[zone]\n        base = tariff[\"first_500\"] + ((weight - 500) // 500) * tariff[\"per_extra_500\"]\n        if service == \"express\":\n            base = (base * 3 + 1) // 2\n        merchandise = sum(item[\"qty\"] * item[\"price\"] for item in items)\n        if service == \"standard\" and merchandise >= rates.FREE_SHIPPING_FROM and not remote:\n            base = 0\n        coupon = order.get(\"coupon\")\n        if coupon == \"SHIP50\":\n            base //= 2\n        elif coupon == \"FREESHIP\":\n            if not remote:\n                base = 0\n        elif coupon is not None:\n            raise QuoteError(\"Unknown coupon\")\n        fees = surcharges.surcharges(items, base, remote)\n        return {\"zone\": zone, \"billable_g\": weight, \"base\": base, \"surcharges\": fees, \"total\": base + sum(fees.values())}\n    except QuoteError:\n        raise\n    except (KeyError, TypeError, ValueError, IndexError) as exc:\n        raise QuoteError(\"Invalid order\") from exc\n"}},
